<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><link rel="stylesheet" href="/public/css/app.css"><title>Mon compte · <?= htmlspecialchars($application['name']) ?></title><body class="outdoor-mode"><?php require __DIR__ . '/../partials/header.php'; ?><main class="auth-page account-page"><h1>Mon compte</h1><p>Rôle : <?= htmlspecialchars($user['role']) ?></p><div class="contribution-counts"><span><?= $counts['proposed'] ?> plantations proposées</span><span><?= $counts['validated'] ?> plantations validées</span><span><?= count($features) ?> arbres proposés</span><span><?= $counts['planted'] ?> arbres plantés</span></div><div id="my-contributions-map" class="account-map"></div><h2>Informations personnelles</h2><form method="post" action="/mon-compte"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars($csrfToken) ?>"><label>Prénom<input name="first_name" value="<?= htmlspecialchars($user['first_name']) ?>" required></label><label>Nom<input name="last_name" value="<?= htmlspecialchars($user['last_name']) ?>" required></label><label>E-mail<input name="email" type="email" value="<?= htmlspecialchars($user['email']) ?>" required></label><button>Enregistrer</button></form></main><?php require __DIR__ . '/../partials/footer.php'; ?><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>const features=<?= json_encode($features,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?>;const map=L.map('my-contributions-map').setView([47.531,-0.102],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap'}).addTo(map);const layer=L.geoJSON({type:'FeatureCollection',features}).addTo(map);if(features.length)map.fitBounds(layer.getBounds(),{padding:[16,16]});</script></body></html>
